.req222-page .menu-profile-results { border: 1px solid #e2e8f0; border-radius: 8px; background: white; }
.req222-page .menu-condition-tabs { display: flex; flex-wrap: wrap; gap: 8px; border-bottom: 1px solid #e2e8f0; padding: 8px 0; }
.req222-page .menu-panel-notice { border: 1px solid #bae6fd; border-radius: 8px; background: #f0f9ff; color: #075985; padding: 16px; margin: 16px 0; }
@media (min-width: 768px) { .req222-page .menu-panel-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

